<script setup lang="ts">
// FR-AUTH-001 / D18-API-001 / TC-AUTH-002
import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '../../stores/auth';import {request} from '../../api/http';import {endpoints} from '../../api/endpoints';import {errorText,type LoginResult} from '../../api/implemented';
import {homePath} from '../../router/navigation';
const orgCode=ref('DEMOLOCAL'),username=ref(''),password=ref(''),error=ref(''),busy=ref(false);const auth=useAuthStore(),router=useRouter();
async function login(){busy.value=true;error.value='';try{const x=await request<LoginResult>(endpoints['D18-API-001'],{},{orgCode:orgCode.value,username:username.value,password:password.value});auth.token=x.accessToken;auth.set(x.user);password.value='';await router.push(homePath(auth.permissions))}catch(e){error.value=errorText(e)}finally{busy.value=false}}
onMounted(()=>{const input=document.querySelector<HTMLInputElement>('input[autocomplete="organization"]');if(!input||!input.parentElement)return;const select=document.createElement('select');select.required=true;select.setAttribute('aria-label','组织代码');const option=document.createElement('option');option.value='DEMOLOCAL';option.text='DEMOLOCAL · 华东智造集团有限公司';select.append(option);select.addEventListener('change',()=>orgCode.value=select.value);input.parentElement.replaceChild(select,input)})
</script><template><div class="login-grid"><div class="login-intro"><span class="eyebrow">ENTERPRISE DATA GOVERNANCE</span><h1>让数据可发现<br>让质量可治理</h1><p>资产 · 标准 · 检测 · 工单 · 审计</p><svg viewBox="0 0 500 220" role="img" aria-label="数据治理流程示意"><defs><linearGradient id="flow"><stop stop-color="#2587c2"/><stop offset="1" stop-color="#62e8ff"/></linearGradient></defs><path d="M50 110L150 55L250 110L350 55L450 110L350 175L250 110L150 175Z" fill="none" stroke="url(#flow)" stroke-width="2"/><g fill="#123c60" stroke="#55cfff" stroke-width="2"><circle cx="50" cy="110" r="23"/><circle cx="150" cy="55" r="23"/><circle cx="250" cy="110" r="30"/><circle cx="350" cy="55" r="23"/><circle cx="450" cy="110" r="23"/><circle cx="350" cy="175" r="23"/><circle cx="150" cy="175" r="23"/></g><g fill="#b8eeff" text-anchor="middle" font-size="11"><text x="50" y="114">资产</text><text x="150" y="59">标准</text><text x="250" y="114">治理</text><text x="350" y="59">检测</text><text x="450" y="114">问题</text><text x="350" y="179">工单</text><text x="150" y="179">审计</text></g></svg><span class="badge">统一身份 · 组织授权 · 业务闭环</span></div><section class="login"><span class="eyebrow">WELCOME BACK</span><h2>登录数据治理中心</h2><p>使用组织代码和已授权的账号登录。</p><form @submit.prevent="login"><label>组织代码<input v-model="orgCode" required maxlength="64" autocomplete="organization" placeholder="请输入组织代码"></label><label>账号<input v-model="username" required maxlength="64" autocomplete="username" placeholder="请输入账号"></label><label>密码<input v-model="password" type="password" required autocomplete="current-password" placeholder="请输入密码"></label><p role="alert" class="error">{{error}}</p><button :disabled="busy">{{busy?'正在登录…':'进入治理工作空间'}}</button></form></section></div></template>
